import os # Freeze CPU policy before launching native nonlinear cases.
os.environ['OPENBLAS_NUM_THREADS']='1' # Bound each independent solver worker.
import json,time,subprocess,concurrent.futures # Execute real native analyses and preserve every outcome.
import numpy as np # Define geometry-isolated load paths and source fields.
from run import load_base # Reuse previously verified local solid geometry without changing it.
from fem import make_case,CCX,sha,write_json # Preserve exact static geometry, material and consistent traction construction.
from nonlinear_mechanics import OUT,FiniteStrain,parse_dat # Apply compatible finite-strain quality checks to every native frame.
PATH=np.array([0.,.25,.5,.75,1.,.5,0.,-.3,-.6,-.3,0.,.4]) # Declare a reversible load-unload-reverse-reload research path.
def run_case(item): # Solve and audit one complete geometrically nonlinear quasi-static trajectory.
    path=np.array(item.get('load_path',PATH));family=item['family'];identity=item['id'];p=item['params'];base=load_base(family);directory=OUT/'cases'/identity;directory.mkdir(parents=True,exist_ok=True);started=time.time() # Preserve fixed geometric identity and physical inputs.
    xyz,K,force,fixed,free,E,volume=make_case(base,p);tet=base[1];groups=base[2];meta=base[3];adapter=FiniteStrain(xyz,tet,groups,E,meta['nu']) # Construct exact reference fields and finite-strain physical adapter.
    lines=['*HEADING',identity,'*NODE']+[f'{i+1},'+','.join(f'{v:.14g}' for v in point) for i,point in enumerate(xyz)] # Write original solid geometry with sufficient numerical precision.
    lines.extend(['*ELEMENT,TYPE=C3D10,ELSET=SOLID']+[f'{i+1},'+','.join(str(n+1) for n in nodes) for i,nodes in enumerate(tet)]+['*MATERIAL,NAME=STEEL','*ELASTIC',f'{E:.14g},{meta["nu"]:.14g}','*SOLID SECTION,ELSET=SOLID,MATERIAL=STEEL','*NSET,NSET=ALL,GENERATE',f'1,{len(xyz)},1','*BOUNDARY']) # Preserve quadratic elements and exact declared PK2 elastic law.
    lines.extend(f'{i//3+1},{i%3+1},{i%3+1},0.' for i in fixed) # Apply unchanged cut-face translational constraints.
    for target in path[1:]: # Run explicit continuation through every loading and reversal stage.
        lines.extend(['*STEP,NLGEOM,INC=150','*STATIC',f"{item.get('increment',.25)},1.,1e-7,{item.get('increment',.25)}",'*CONTROLS,PARAMETERS=FIELD','1e-8,1e-8,,,1e-8,1e-8,1e-6,1e-10','*CLOAD,OP=NEW']) # Tighten native nonlinear residual and increment control without loosening independent gates.
        lines.extend(f'{i//3+1},{i%3+1},{value*target:.14g}' for i,value in enumerate(force) if value!=0) # Retain the same spatial force pattern with signed target amplitude.
        lines.extend(['*NODE PRINT,NSET=ALL,FREQUENCY=1','U,RF','*NODE FILE,FREQUENCY=999','U,RF','*EL FILE,FREQUENCY=999','S','*END STEP']) # Save native stage-endpoint nodal fields under the shared output-frequency setting.
    inp=directory/'model.inp';inp.write_text('\n'.join(lines)+'\n');env=dict(os.environ,OMP_NUM_THREADS='1',CCX_NPROC_RESULTS='1');status='NUMERICAL_FAILURE' # Preserve actual source before solve and assume failure until audited.
    with (directory/'solver.log').open('w') as log: process=subprocess.run([str(CCX),'-i','model'],cwd=directory,env=env,stdout=log,stderr=subprocess.STDOUT,timeout=240) # Execute genuine nonlinear finite-element continuation.
    log=(directory/'solver.log').read_text();frames=parse_dat(directory/'model.dat',len(xyz));evidence=[];endpoints={0.:np.zeros_like(xyz)};native_complete=process.returncode==0 and 'Job finished' in log and '*ERROR' not in log # Require explicit native completion and complete result tables.
    for pseudo_time,fields in frames: # Audit each actual nonlinear increment rather than just final displacement.
        assert np.isfinite(fields['u']).all() and np.isfinite(fields['rf']).all();stage=min(int(np.floor(pseudo_time-1e-8)),len(path)-2);fraction=pseudo_time-stage;amplitude=path[stage]+fraction*(path[stage+1]-path[stage]);external=force.reshape(-1,3)*amplitude;internal,diagnostics=adapter.internal(fields['u']) # Recover actual load state and consistent total-Lagrangian internal forces.
        residual=(internal-external).ravel();relative=float(np.linalg.norm(residual[free])/max(np.linalg.norm(force),1.));support=internal.copy();support.reshape(-1)[free]=0.;global_force=float(np.linalg.norm((support+external).sum(axis=0))/max(np.linalg.norm(force.reshape(-1,3).sum(axis=0)),1.));coordinates=xyz+fields['u'];moment=float(np.linalg.norm(np.cross(coordinates,support+external).sum(axis=0))/max(np.linalg.norm(np.cross(xyz,force.reshape(-1,3)).sum(axis=0)),1.)) # Measure local force equilibrium and global finite-configuration balance.
        evidence.append({'pseudo_time':pseudo_time,'load_amplitude':float(amplitude),'full_residual_peak_load_normalized':relative,'global_force_relative':global_force,'global_moment_relative':moment,**diagnostics}) # Preserve displacement-compatible nonlinear physical metrics.
        if abs(pseudo_time-round(pseudo_time))<1e-6: endpoints[float(round(pseudo_time))]=fields['u'] # Select exact continuation-stage endpoints without interpolating nonlinear labels.
    complete=len(endpoints)==len(path);maximum=max(x['full_residual_peak_load_normalized'] for x in evidence);positive=min(x['min_J'] for x in evidence)>0;qualified=native_complete and complete and positive and maximum<1e-6 # Apply frozen research numerical acceptance before training.
    trajectory=np.array([endpoints.get(float(i),np.full_like(xyz,np.nan)) for i in range(len(path))]);np.savez_compressed(directory/'trajectory.npz',xyz=xyz,tet=tet,groups=groups,force=force,free=free,fixed=fixed,params=p,load_path=path,displacement=trajectory,E=E,nu=meta['nu']) # Save complete native-derived trajectory and physical reconstruction inputs.
    receipt={**item,'status':'VALID_CONVERGED' if qualified else 'QUARANTINED','native_complete':native_complete,'endpoint_count':len(endpoints),'increment_count':len({round(float(line.split()[4]),8) for line in (directory/'model.sta').read_text().splitlines() if len(line.split())==7 and all(v.isdigit() for v in line.split()[:4])}|{round(t,8) for t,_ in frames}),'printed_frame_count':len(frames),'physical_audit_scope':'All printed stage-endpoint fields; intermediate increments counted from native STA.','max_nonlinear_residual':maximum,'seconds':time.time()-started,'input_sha256':sha(inp),'dat_sha256':sha(directory/'model.dat'),'frd_sha256':sha(directory/'model.frd'),'frames':evidence,'limitations':'Quasi-static geometrical nonlinearity with St-Venant Kirchhoff elastic law; no contact, yielding, damage or inertial dynamics.'};write_json(directory/'receipt.json',receipt);return receipt # Keep true nonlinear label qualification separate from physical applicability.
def main(): # Generate fixed geometry-isolated trajectories and run every declared task.
    OUT.mkdir(exist_ok=True);manifest=[] # Freeze all dataset identities before computation.
    for family in ['splice','deck']: # Cover substantial coupon rotations and ribbed-plate geometry.
        random=np.random.default_rng(142 if family=='splice' else 143).random((14,6)) # Fix independent structural parameter draws.
        for i,row in enumerate(random): # Separate geometric instances between fitting, selection and testing.
            p=(np.array([.9,.9,.9,.9,1.5,.25])+row*np.array([.2,.2,.2,.2,1.5,.5])).tolist();split='train' if i<8 else ('validation' if i<11 else 'test');manifest.append({'id':f'{family}_g{i:02d}','family':family,'geometry_id':f'{family}_g{i:02d}','split':split,'params':p}) # Declare actual load magnitude, center and geometry changes.
    write_json(OUT/'manifest.json',manifest);write_json(OUT/'contract.json',{'load_path':PATH.tolist(),'native_solver':str(CCX),'kinematics':'F=I+grad(u); E=(F.T F-I)/2; S=lambda tr(E)I+2muE; P=F S','integration':'C3D10 four-point reference tetrahedron','threshold':1e-6,'normalization':'all printed endpoint residuals divided by peak nodal-force vector norm, including zero-load states','split':'geometry-disjoint 8 training / 3 validation / 3 testing per family','material_source':'https://www.dhondt.de/ccx_2.21.pdf section 6.8.1','contact':'excluded; separate contact-validation experiment'}) # Freeze nonlinear physics and label rules before execution.
    with concurrent.futures.ProcessPoolExecutor(max_workers=3) as pool: # Bound concurrent actual native nonlinear workloads.
        results=[] # Preserve every task, including any failed geometry.
        for result in pool.map(run_case,manifest): results.append(result);write_json(OUT/'native_results.json',results);print(result['id'],result['status'],result['max_nonlinear_residual'],result['seconds'],flush=True) # Checkpoint each completed physical path.
if __name__=='__main__': main() # Execute full nonlinear continuation dataset generation.
